8	/**
9	 * Emits an audit line on the dedicated {@code AUDIT} logger for a successful create. Runs after
10	 * {@link SaveOwner}, so the owner has its persisted id, and after {@link AssignCustomerCode}, so
11	 * the {@code customerCode} is set. The line carries the owner id, the customerCode and the
12	 * (business-day-adjusted) registrationDate, the numeric membershipLevel and the membershipNumber.
13	 */
14	public class AuditOwnerCreated {
15	
16	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
17	
18	    public void service(@Val Owner owner) {
19	        AUDIT.info(
20	                "owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
21	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
22	                owner.getMembershipLevel(), owner.getMembershipNumber());
23	    }
24	}
