1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import java.util.HashSet;
8	import java.util.Set;
9	
10	import net.officefloor.plugin.variable.Val;
11	import org.springframework.samples.petclinic.model.Owner;
12	import org.springframework.samples.petclinic.repository.OwnerRepository;
13	
14	/**
15	 * Assigns the owner's {@code customerCode}, formatted {@code <REGION>-<HASH8>} where REGION is
16	 * the region code derived from the postcode (see {@link OwnerRegion}) and HASH8 is the first 8
17	 * upper-case hex characters of the SHA-256 digest over the normalized telephone concatenated with
18	 * the last name (e.g. {@code NSW-1A2B3C4D}). There are no per-city sequence numbers.
19	 *
20	 * <p>Runs after {@link BuildOwner} (so the normalized telephone, last name and postcode are on the
21	 * owner) and before {@link SaveOwner}. The membership number, its Luhn check digit, the create
22	 * audit line and the derived locality all read this identity.
23	 *
24	 * <p>If the computed code collides with an existing owner's {@code customerCode}, it is
25	 * de-duplicated by appending {@code -<n>} with the smallest {@code n} of 2 or more that makes it
26	 * unique.
27	 */
28	public class AssignCustomerCode {
29	
30	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
31	        String region = OwnerRegion.fromPostcodeOrCity(owner.getPostcode(), owner.getCity());
32	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
33	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
34	        String base = region + "-" + hash8(telephone + lastName);
35	        owner.setCustomerCode(deDuplicate(base, owner, ownerRepository));
36	    }
37	
38	    /**
39	     * Returns {@code base} if no existing owner already uses it, otherwise {@code base-<n>} with the
40	     * smallest {@code n >= 2} that is not already taken by an existing owner.
41	     */
42	    private static String deDuplicate(String base, Owner owner, OwnerRepository ownerRepository) {
43	        Set<String> taken = new HashSet<>();
44	        for (Owner existing : ownerRepository.findAll()) {
45	            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
46	                continue; // never compare the new owner against itself
47	            }
48	            String code = existing.getCustomerCode();
49	            if (code != null) {
50	                taken.add(code);
51	            }
52	        }
53	        if (!taken.contains(base)) {
54	            return base;
55	        }
56	        for (int n = 2; ; n++) {
57	            String candidate = base + "-" + n;
58	            if (!taken.contains(candidate)) {
59	                return candidate;
60	            }
61	        }
62	    }
63	
64	    /** First 8 upper-case hex characters of SHA-256 over the UTF-8 bytes of {@code value}. */
65	    private static String hash8(String value) {
66	        try {
67	            byte[] digest = MessageDigest.getInstance("SHA-256")
68	                    .digest(value.getBytes(StandardCharsets.UTF_8));
69	            StringBuilder sb = new StringBuilder(16);
70	            for (int i = 0; i < 4; i++) {
71	                sb.append(String.format("%02X", digest[i]));
72	            }
73	            return sb.toString();
74	        }
75	        catch (NoSuchAlgorithmException e) {
76	            throw new IllegalStateException("SHA-256 not available", e);
77	        }
78	    }
79	}
