1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	
8	/**
9	 * Scores the owner's {@code membershipPoints} at creation, then maps them to a numeric
10	 * {@code membershipLevel} (1 to 4).
11	 *
12	 * <p>Points start at {@code 0}; add {@code 2} when an email is present; add {@code 1} when
13	 * {@code namesakeCount} is {@code 0}; add {@code 2} for a household of {@code 3} or more; add
14	 * {@code 3} when at least one fiscal year has elapsed since registration.
15	 *
16	 * <p>Points map to level as: 1 for 0-1 points, 2 for 2-3 points, 3 for 4-5 points, 4 for 6 or
17	 * more points.
18	 *
19	 * <p>Level 4 requires 6 points, and the only route to 6 is the tenure factor (+3). A newly
20	 * created owner has zero tenure (it registers in the current fiscal year), so the tenure factor
21	 * never applies at creation and a new owner never exceeds level 3.
22	 *
23	 * <p>Runs after {@link AssignNamesakeCount} and {@link AssignHouseholdSize} (so those counts are
24	 * set) and before {@link SaveOwner}, so both fields are persisted and available to the create
25	 * audit line.
26	 */
27	public class AssignMembershipLevel {
28	
29	    /** Tenure threshold, in elapsed fiscal years, at or above which the tenure factor is awarded. */
30	    private static final int TENURE_FISCAL_YEARS_THRESHOLD = 1;
31	
32	    public void service(@Val Owner owner) {
33	        int points = 0;
34	        String email = owner.getEmail();
35	        if (email != null && !email.isBlank()) {
36	            points += 2;
37	        }
38	        if (Integer.valueOf(0).equals(owner.getNamesakeCount())) {
39	            points += 1;
40	        }
41	        Integer householdSize = owner.getHouseholdSize();
42	        if (householdSize != null && householdSize >= 3) {
43	            points += 2;
44	        }
45	        if (tenureFiscalYears(owner) >= TENURE_FISCAL_YEARS_THRESHOLD) {
46	            points += 3;
47	        }
48	        owner.setMembershipPoints(points);
49	        owner.setMembershipLevel(levelForPoints(points));
50	    }
51	
52	    /** Maps points to level: 1 (0-1), 2 (2-3), 3 (4-5), 4 (6 or more). */
53	    private static int levelForPoints(int points) {
54	        if (points >= 6) {
55	            return 4;
56	        }
57	        if (points >= 4) {
58	            return 3;
59	        }
60	        if (points >= 2) {
61	            return 2;
62	        }
63	        return 1;
64	    }
65	
66	    /**
67	     * Whole fiscal years elapsed since registration; zero (or negative) for an owner registered in
68	     * the current fiscal year.
69	     */
70	    private static int tenureFiscalYears(Owner owner) {
71	        LocalDate registrationDate = owner.getRegistrationDate();
72	        if (registrationDate == null) {
73	            return 0;
74	        }
75	        return FiscalYear.elapsed(registrationDate, LocalDate.now());
76	    }
77	}
