3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	
6	/**
7	 * Assigns the owner's {@code membershipNumber}, formatted {@code <customerCode>-M<YY>} where
8	 * {@code <customerCode>} is the owner's already-assigned region-and-hash customer code and
9	 * {@code YY} is the last two digits of the fiscal year's start-year for the business-day-adjusted
10	 * {@code registrationDate} (the same {@code YY} as the owner's {@code fiscalYear}, e.g.
11	 * {@code NSW-1A2B3C4D-M26}).
12	 *
13	 * <p>Runs after {@link AssignCustomerCode} (so the customer code exists) and after
14	 * {@link BuildOwner} (so the registration date is set), and before {@link SaveOwner}.
15	 */
16	public class AssignMembershipNumber {
17	
18	    public void service(@Val Owner owner) {
19	        String yy = String.format("%02d", FiscalYear.startYear(owner.getRegistrationDate()) % 100);
20	        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
21	    }
22	}
