1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * Caps the new owner's {@code membershipLevel} so it cannot exceed one above the current maximum
10	 * {@code membershipLevel} among the existing members of its household (owners sharing the same
11	 * {@link AssignHouseholdId#deriveHouseholdId householdId}). A joining member cannot leapfrog the
12	 * household: the level becomes {@code min(assignedLevel, maxExistingMemberLevel + 1)}.
13	 *
14	 * <p>The cap targets a <em>silent</em> joiner — one admitted into the household by
15	 * {@link RequireUniqueOwnerHousehold} on the strength of its own distinct email rather than by
16	 * declaring {@code sharesHousehold}. A member the caller explicitly declares with
17	 * {@code sharesHousehold} true is trusted and keeps its assigned level, so the tenure/points model
18	 * (e.g. the household-size bonus that lifts a declared third member to level 3) is preserved.
19	 *
20	 * <p>When there is no existing household member — the owner has no {@code householdId}, or is the
21	 * only member so far — no cap applies and the assigned level is left untouched.
22	 *
23	 * <p>Runs after {@link AssignMembershipLevel} (which assigns the uncapped level) and before
24	 * {@link SaveOwner}, so the capped value is what is persisted and returned. The new owner is not
25	 * yet saved, so the repository scan sees only the pre-existing members.
26	 */
27	public class CapMembershipLevel {
28	
29	    public void service(@Val OwnerFieldsDto request, @Val Owner owner,
30	            OwnerRepository ownerRepository) {
31	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
32	            return; // a declared household member is trusted and not capped
33	        }
34	        String householdId = owner.getHouseholdId();
35	        if (householdId == null) {
36	            return;
37	        }
38	        Integer level = owner.getMembershipLevel();
39	        if (level == null) {
40	            return;
41	        }
42	        Integer maxExisting = null;
43	        for (Owner existing : ownerRepository.findAll()) {
44	            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
45	                continue; // never count the new owner against itself
46	            }
47	            if (Boolean.TRUE.equals(existing.getDeleted())) {
48	                continue; // a soft-deleted owner is not a household member
49	            }
50	            if (!householdId.equals(existing.getHouseholdId())) {
51	                continue;
52	            }
53	            Integer existingLevel = existing.getMembershipLevel();
54	            if (existingLevel != null && (maxExisting == null || existingLevel > maxExisting)) {
55	                maxExisting = existingLevel;
56	            }
57	        }
58	        if (maxExisting == null) {
59	            return; // no existing household member -> no cap applies
60	        }
61	        int ceiling = maxExisting + 1;
62	        if (level > ceiling) {
63	            owner.setMembershipLevel(ceiling);
64	        }
65	    }
66	}
